YEAR={'achema':2024,'tps':2024,'petro24':2024,'pv25':2025,'tfs25':2025,'leuna25':2025,'cru25':2025,'lh25':2025}
def tile(f):
    k,name,ort,dat,hero,more,chips,txt,tk,link=f
    g='m_'+k
    if hero is None:
        ch=''.join(f'<span>{T(*c)}</span>' for c in chips)
        return (f'<article class="ft"><div class="mi noimg"><b>{name}</b></div><div class="fx"><span class="client">{T(*dat)} · {T(*ort)}</span><h3>{name}</h3><div class="chips">{ch}</div>'
                f'<details><summary>{T("Mehr erfahren","Learn more")}</summary><div class="fd">{P(*txt)}{tasks(*tk)}</div></details></div></article>')
    G[g]=[(s,name) for s in [hero]+more]
    ch=''.join(f'<span>{T(*c)}</span>' for c in chips)
    lk=f'<a class="lnk" href="{A}{link}" target="_blank" rel="noopener">{T("Ganze Projektseite","Full project page")} ↗</a>' if link else ''
    n=len(G[g]); badge=f'<span class="cnt">{n} {T("Bilder","images")}</span>' if n>1 else ''
    return (f'<article class="ft"><button class="mi" data-gallery="{g}" data-n="0" aria-label="{name}"><img src="img/{hero}" alt="{name}">{badge}</button>'
            f'<div class="fx"><span class="client">{T(*dat)} · {T(*ort)}</span><h3>{name}</h3><div class="chips">{ch}</div>'
            f'<details><summary>{T("Mehr erfahren","Learn more")}</summary><div class="fd">{P(*txt)}{tasks(*tk)}{lk}</div></details></div></article>')
def grid(keys): return '<div class="fgrid">'+''.join(tile(f) for f in F if f[0] in keys)+'</div>'
y26=[f[0] for f in F if '2026' in f[1]]; y25=[f[0] for f in F if '2025' in f[1]]; y24=[f[0] for f in F if '2024' in f[1]]
intl=(f'<div class="yr"><h4>2026</h4></div>'+grid(y26)+f'<div class="yr"><h4>2025</h4></div>'+grid(y25)+f'<div class="yr"><h4>2024</h4></div>'+grid(y24))
